// src/components/AdminGallery.jsx
import React, { useEffect, useState, useRef } from "react";
import axios from "axios";
import toast, { Toaster } from "react-hot-toast";
import "../styles/main.css";

export default function AdminGallery() {
  const [images, setImages] = useState([]);
  const [selectedFiles, setSelectedFiles] = useState([]);
  const [loading, setLoading] = useState(false);
  const dropRef = useRef();

  // Fetch gallery images from server
  const fetchImages = async () => {
    try {
      const res = await axios.get("http://localhost:5000/api/admin/gallery");
      setImages(res.data.data || []);
    } catch (err) {
      console.error(err);
      toast.error("Failed to load images");
    }
  };

  useEffect(() => {
    fetchImages();
  }, []);

  // Handle files from input or drag/drop
  const handleFiles = (files) => {
    const fileArr = Array.from(files);
    setSelectedFiles((prev) => [...prev, ...fileArr]);
  };

  // Upload selected files
  const handleUpload = async () => {
    if (selectedFiles.length === 0) return toast.error("Select files first");
    const formData = new FormData();
    selectedFiles.forEach((file) => formData.append("images", file));

    setLoading(true);
    try {
      const res = await axios.post(
        "http://localhost:5000/api/admin/gallery",
        formData,
        { headers: { "Content-Type": "multipart/form-data" } }
      );
      if (res.data.success) {
        toast.success("Images uploaded!");
        setSelectedFiles([]);
        fetchImages();
      } else toast.error(res.data.error || "Upload failed");
    } catch (err) {
      console.error(err);
      toast.error("Upload failed");
    }
    setLoading(false);
  };

  const handleDelete = async (id) => {
    if (!window.confirm("Delete this image?")) return;
    try {
      const res = await axios.delete(`http://localhost:5000/api/admin/gallery/${id}`);
      if (res.data.success) {
        toast.success("Image deleted!");
        fetchImages();
      } else toast.error(res.data.error || "Delete failed");
    } catch (err) {
      console.error(err);
      toast.error("Delete failed");
    }
  };

  // Drag & Drop events
  const handleDragOver = (e) => {
    e.preventDefault();
    dropRef.current.classList.add("drag-over");
  };

  const handleDragLeave = (e) => {
    e.preventDefault();
    dropRef.current.classList.remove("drag-over");
  };

  const handleDrop = (e) => {
    e.preventDefault();
    dropRef.current.classList.remove("drag-over");
    handleFiles(e.dataTransfer.files);
  };

  return (
    <div className="admin-gallery-page">
      <Toaster />
      <h2>Manage Gallery</h2>

      {/* Drag & Drop + File Input */}
      <div
        className="upload-section"
        ref={dropRef}
        onDragOver={handleDragOver}
        onDragLeave={handleDragLeave}
        onDrop={handleDrop}
      >
        <p>Drag & Drop images here or click to select</p>
        <input
          type="file"
          multiple
          onChange={(e) => handleFiles(e.target.files)}
        />
      </div>

      {/* Preview selected files */}
      {selectedFiles.length > 0 && (
        <div className="preview-grid">
          {selectedFiles.map((file, idx) => (
            <div key={idx} className="preview-card">
              <img src={URL.createObjectURL(file)} alt="Preview" />
            </div>
          ))}
        </div>
      )}

      <button
        className="upload-btn"
        onClick={handleUpload}
        disabled={loading || selectedFiles.length === 0}
      >
        {loading ? "Uploading..." : "Upload Selected Images"}
      </button>

      {/* Existing gallery images */}
      <div className="gallery-grid">
        {images.length === 0 && <p>No images yet.</p>}
        {images.map((img) => (
          <div className="gallery-card" key={img.id}>
            <img src={img.url} alt="Gallery" />
            <button className="delete-btn" onClick={() => handleDelete(img.id)}>
              Delete
            </button>
          </div>
        ))}
      </div>
    </div>
  );
}
